using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using Chaos.ListExtensions;
using Rewired;
using Steamworks;
using UnityEngine;

public class GameController : MonoBehaviour
{
	public delegate void LevelLoadEventHandler(string nextLevel, string prevLevelName);

	private static GameController instance = null;

	public static readonly int maxPlayerCount = 2;

	public static Player[] playerScripts;

	public static Player[] activePlayers = new Player[0];

	public static List<GameObject> players;

	public static List<GameObject> ghosts;

	public static List<GameObject> allies;

	public static List<GameObject> enemies;

	public static List<GameObject> bosses;

	private static List<Player> previousPlayers;

	public static string prevLevelName;

	public static string queuedLevelName;

	public static string lastTierName = string.Empty;

	public static string currentLevelName = string.Empty;

	public static int skipLevelLoadFrames;

	public static int curSkipLevelLoadFrame;

	public static int levelGold = 0;

	public static int totalGold = 0;

	public static int levelPlat = 0;

	public static int totalPlat = 0;

	public static float levelTime = 0f;

	public static float lastTotalTime = 0f;

	public static float totalTime = 0f;

	public static float timeSinceLastTimeSave = 0f;

	public static bool pauseTimer;

	public static bool inGameScene = false;

	public static int startingDifficulty = 0;

	public static readonly int stagesPerTier = 1;

	public static readonly int stagesPerRush = 0;

	public static readonly int maxBaseTierCount = 3;

	public static int stageCount = 0;

	public static int tierCount = 0;

	public static int loopCount = 0;

	public static InputManager rewiredInput;

	public static SoundManager soundManager;

	public static CameraController cameraController;

	public static ItemSpawner itemSpawner;

	public static LevelSummary levelSummary;

	public static LoadingScreen loadingScreen;

	public static ChaosLogger logger;

	public static SkillStoreUI skillStoreUI;

	public static CharacterSelectUI characterSelectUI;

	public static ChaosMouseCursor mouseCursor;

	public static StageTitleUI stageTitleUI;

	public static GameUI gameUI;

	public static RunHistoryUI runHistoryUI;

	public static DebugMenu debugMenu;

	public static OptionsMenu optionsMenu;

	public static Minimap minimap;

	public static MinimapFullscreen minimapFullscreen;

	public static UnlockNotifier unlockNotifier;

	public static OverlayEffects overlayEffects;

	public static PlayerStatusBar[] playerStatusBars;

	public static Compass compass;

	public static RunModifier runModifier;

	public static bool hideUI = false;

	public static bool pausePressed = false;

	public static bool pauseQueued = false;

	public static bool loadingPauseQueued = false;

	public static bool resetCameraOnLoadLevel = true;

	public static bool resetGameDataQueued = false;

	public static bool pvp = false;

	public static bool coopOn = false;

	public static bool p1Joined = false;

	public static bool p2Joined = false;

	public static Dictionary<string, string> bossLevelNameDict = new Dictionary<string, string>
	{
		{ "Ice", "IceBossLevel" },
		{ "Earth", "EarthBossLevel" },
		{ "Fire", "FireBossLevel" },
		{ "Air", "AirBossLevel" },
		{ "Lightning", "LightningBossLevel" }
	};

	public static List<string> levelNameList = new List<string> { "Ice", "Earth", "Fire", "Air", "Lightning" };

	public static Light stageLight = null;

	public static bool coreDependenciesLoaded = false;

	public static bool secondaryDependenciesLoaded = false;

	public static bool effectsPoolsLoaded = false;

	public static LevelLoadEventHandler levelLoadEventHandlers;

	public static bool resetHubVars;

	protected Callback<GameOverlayActivated_t> m_GameOverlayActivated;

	public static int callbackType = 0;

	public static ControllerMap keyboardMap = null;

	public static ControllerMap mouseMap = null;

	public static GameController Instance => instance;

	public static int CurrentDifficulty => loopCount * maxBaseTierCount + tierCount + startingDifficulty;

	public static int MaxTierCount => (!Level.isBossRushMode) ? 3 : 5;

	public static string CurrentSceneName => Application.loadedLevelName switch
	{
		"Ice" => TextManager.GetUIText("stageTitle-iceStage"), 
		"IceBossLevel" => TextManager.GetUIText("enemyName-bossIce"), 
		"Earth" => TextManager.GetUIText("stageTitle-earthStage"), 
		"EarthBossLevel" => TextManager.GetUIText("enemyName-bossEarth"), 
		"Fire" => TextManager.GetUIText("stageTitle-fireStage"), 
		"FireBossLevel" => TextManager.GetUIText("enemyName-bossFire"), 
		"Air" => TextManager.GetUIText("stageTitle-airStage"), 
		"AirBossLevel" => TextManager.GetUIText("enemyName-bossAir"), 
		"Lightning" => TextManager.GetUIText("stageTitle-lightningStage"), 
		"LightningBossLevel" => TextManager.GetUIText("enemyName-bossLightning"), 
		"FinalBossLevel" => TextManager.GetUIText("enemyName-bossChaos"), 
		_ => string.Empty, 
	};

	public static string CurrentStageStr => loopCount * maxBaseTierCount + tierCount + 1 + "-" + stageCount;

	public static string StageTitle => TextManager.GetUIText("gameController-stageTitle") + " " + CurrentStageStr;

	public static bool pvpOn => pvp;

	public static string NextLevelName
	{
		get
		{
			return levelNameList[0];
		}
		set
		{
			levelNameList.Shuffle();
			if (value != string.Empty && levelNameList.Contains(value))
			{
				levelNameList.Remove(value);
				levelNameList.Insert(0, value);
			}
			if (loadingScreen != null && loadingScreen.gameProgressBoard != null)
			{
				loadingScreen.gameProgressBoard.InitializeTierOrders();
			}
		}
	}

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		if (!ChaosBundle.bundleLoaded)
		{
			ChaosBundle.LoadBundle();
		}
		ChaosStopwatch.InitStopwatch();
		InitData();
		InitEntityLists();
		InitializeScene();
		LootManager.Initialize();
		ChaosCollisions.InitializeLayermasks();
		NextLevelName = string.Empty;
	}

	private void Start()
	{
		queuedLevelName = string.Empty;
		curSkipLevelLoadFrame = 0;
		skipLevelLoadFrames = 2;
		if (playerScripts[0] != null)
		{
			p1Joined = true;
		}
		if (playerScripts[1] != null)
		{
			p2Joined = true;
		}
		cameraController = Camera.main.GetComponent<CameraController>();
		TextManager.SetAllUITexts();
		if (SteamManager.Initialized)
		{
			m_GameOverlayActivated = Callback<GameOverlayActivated_t>.Create(OnGameOverlayActivated);
		}
	}

	public static void TogglePvpMode(bool pvpStatus)
	{
		pvp = pvpStatus;
		int maxSkillLevel = SkillStats.maxSkillLevel;
		if (pvp)
		{
			Player[] array = activePlayers;
			foreach (Player player in array)
			{
				foreach (KeyValuePair<string, StatData> item in StatManager.data["Skills"][player.skillCategory])
				{
					for (int j = 0; j <= maxSkillLevel; j++)
					{
						List<string> value = item.Value.GetValue<List<string>>("targetNames", j);
						if (value.Contains(Globals.enemyHBStr) && !value.Contains(Globals.allyHBStr))
						{
							value.Add(Globals.allyHBStr);
						}
						if (value.Contains(Globals.enemyFCStr) && !value.Contains(Globals.allyFCStr))
						{
							value.Add(Globals.allyFCStr);
						}
					}
				}
			}
			return;
		}
		Player[] array2 = activePlayers;
		foreach (Player player2 in array2)
		{
			foreach (KeyValuePair<string, StatData> item2 in StatManager.data["Skills"][player2.skillCategory])
			{
				for (int l = 0; l <= maxSkillLevel; l++)
				{
					List<string> value = item2.Value.GetValue<List<string>>("targetNames", l);
					value.Remove(Globals.allyHBStr);
					value.Remove(Globals.allyFCStr);
				}
			}
		}
	}

	public static void DisplayLoadingScreen(string levelName)
	{
		PauseAllPlayers();
		Player[] array = activePlayers;
		foreach (Player player in array)
		{
			if (!(player == null))
			{
				player.Hide();
			}
		}
		if (NextLevelLoader.InTierScene(levelName) || bossLevelNameDict.Values.Contains(levelName) || levelName.Contains("FinalBoss"))
		{
			loadingScreen.SetPromptText(string.Empty);
			loadingScreen.SetProgressText(string.Empty);
			loadingScreen.Enable(gameProgressMode: true);
		}
		else if (levelName == "Credits" || levelName == "PlayerRoomTutorial")
		{
			loadingScreen.SetPromptText(string.Empty);
			loadingScreen.SetProgressText(string.Empty);
			loadingScreen.Enable();
		}
		else
		{
			loadingScreen.SetPromptText(TextManager.GetUIText("loadingScreen-loading"));
			loadingScreen.SetProgressText(string.Empty);
			loadingScreen.Enable();
		}
	}

	public static void Quit()
	{
		Process.GetCurrentProcess().Kill();
	}

	public static void LoadLevel(string givenLevelName)
	{
		if (queuedLevelName == string.Empty)
		{
			curSkipLevelLoadFrame = skipLevelLoadFrames;
			queuedLevelName = givenLevelName;
			DisplayLoadingScreen(givenLevelName);
			players.Clear();
			ghosts.Clear();
			allies.Clear();
			enemies.Clear();
			bosses.Clear();
			previousPlayers.Clear();
			ClearLevelStats();
			if (itemSpawner != null)
			{
				itemSpawner.Reset();
			}
			return;
		}
		prevLevelName = Application.loadedLevelName;
		if (overlayEffects != null)
		{
			overlayEffects.anim.Play("Hidden");
		}
		NextLevelLoader.SetLevelInfo(givenLevelName);
		GameUI.dialogManager.Deactivate(resetDialog: true);
		GameUI.SetMoneyStatus(givenLevelName != "Tutorial" && givenLevelName != "Epilogue");
		PauseAllPlayers();
		GameDataManager.Save(updateCurrentData: true, prevLevelName == "PlayerRoom" || prevLevelName == "PvP");
		queuedLevelName = string.Empty;
		curSkipLevelLoadFrame = 0;
		SkillStoreItem.ResetSpawnedSkills();
		ItemStoreItem.ResetSpawnedItems();
		LootManager.Reset();
		if (resetCameraOnLoadLevel)
		{
			cameraController.vertMoveOnly = false;
			cameraController.horiMoveOnly = false;
			cameraController.overrideCameraUpdate = false;
			cameraController.disablePlayerTracking = false;
			cameraController.lockToSpawnPos = false;
		}
		Outfit.UpdateStarterOutfits(givenLevelName);
		pauseTimer = false;
		bool flag;
		Player[] array;
		switch (givenLevelName)
		{
		case "PlayerRoom":
			if (!(prevLevelName != "Hub"))
			{
				goto default;
			}
			goto case "InitialLoad";
		default:
			switch (givenLevelName)
			{
			case "Tutorial":
			case "PlayerRoomTutorial":
			case "Epilogue":
				break;
			default:
				goto IL_02aa;
			}
			goto case "InitialLoad";
		case "InitialLoad":
		case "TitleScreen":
			{
				Player[] array2 = activePlayers;
				foreach (Player player2 in array2)
				{
					Object.DestroyImmediate(player2.gameObject);
				}
				p1Joined = false;
				p2Joined = false;
				Level.isBossRushMode = false;
				Level.removeAllPits = false;
				Level.resetUsedRooms = true;
				HealStoreItem.healBuyCount = 0;
				SkillStoreItem.empoweredBuyCount = 0;
				if (Player.goldWallet != null)
				{
					Player.goldWallet.balance = 0;
				}
				HubEventHandler.cursePurchased = false;
				if (givenLevelName != "Epilogue")
				{
					stageCount = 0;
					tierCount = 0;
					loopCount = 0;
					NextLevelName = string.Empty;
					RunData.Reset();
				}
				EnemyGlobalStatManager.ResetScaling();
				resetHubVars = true;
				break;
			}
			IL_02aa:
			characterSelectUI.Disable();
			p1Joined = playerScripts[0] != null;
			p2Joined = playerScripts[1] != null;
			if (Globals.InGameScene(givenLevelName))
			{
				if (levelNameList.Contains(givenLevelName))
				{
					lastTierName = givenLevelName;
				}
				stageCount++;
				EnemyGlobalStatManager.CalculateScaling();
			}
			LootManager.SetCoopGoldMod = coopOn;
			flag = givenLevelName != "FinalBossLevel" && (givenLevelName.Contains("BossLevel") || givenLevelName.Contains("Ending"));
			if (flag)
			{
				cameraController.transform.position = Vector3.up;
				cameraController.VertMoveOnly = true;
			}
			array = activePlayers;
			foreach (Player player in array)
			{
				previousPlayers.Add(player);
				player.RegisterPlayer();
				if (flag)
				{
					player.myOrigin = Vector3.zero;
				}
				player.lastCheckpoint = Vector2.zero;
				if (player.health.healthStat.CurrentValue <= 0f)
				{
					if (coopOn)
					{
						player.ResetPlayer(originPosition: true, fullyRestoreHealth: false, resetState: true, resetOverdrive: true, 0.15f);
					}
					else
					{
						player.ResetPlayer(originPosition: true, fullyRestoreHealth: true, resetState: false);
					}
				}
				else
				{
					player.ResetPlayer(originPosition: true, fullyRestoreHealth: false, resetState: false);
				}
				player.Hide();
				if (prevLevelName != givenLevelName)
				{
					player.transform.position = Vector3.zero;
				}
				player.overheadPrompt.HidePrompt(string.Empty);
			}
			if (givenLevelName != "Hub")
			{
				resetHubVars = false;
				if (givenLevelName != "PlayerRoom")
				{
					RunData.InitRun();
				}
			}
			if (Globals.InGameScene(givenLevelName))
			{
				AchievementManager.UnlockAchievement(Achievement.StartCoopRun);
			}
			break;
		}
		if (givenLevelName == "Ending")
		{
			RunData.EndRun();
			if (totalTime < 1500f)
			{
				AchievementManager.UnlockAchievement(Achievement.SpeedRun, forceUnlock: true);
			}
			lastTotalTime = totalTime;
			RunHistoryEntry.Save();
		}
		Player[] array3 = activePlayers;
		foreach (Player player3 in array3)
		{
			if (player3 != null && player3.hurtBoxObj != null)
			{
				player3.hurtBoxObj.SetActive(value: true);
			}
		}
		if (levelLoadEventHandlers != null)
		{
			levelLoadEventHandlers(givenLevelName, prevLevelName);
		}
		currentLevelName = givenLevelName;
		Application.LoadLevel(givenLevelName);
	}

	private void OnLevelWasLoaded(int level)
	{
		if (instance != null && instance != this)
		{
			return;
		}
		RenderSettings.ambientLight = GameDataManager.gameSettings.brightness * Color.white;
		inGameScene = Globals.InGameScene(Application.loadedLevelName);
		GameUI.RefreshCDUI();
		Player[] array = activePlayers;
		foreach (Player player in array)
		{
			player.fall.ignoreFall.RemoveMod("LevelLoad");
		}
		GameObject gameObject;
		if (cameraController != null)
		{
			gameObject = GameObject.Find("CameraSpawnArea");
			if (gameObject != null)
			{
				cameraController.transform.position = gameObject.transform.position;
			}
			else
			{
				cameraController.transform.position = cameraController.spawnPos;
			}
		}
		gameObject = GameObject.Find("StageLight");
		if (gameObject != null)
		{
			stageLight = gameObject.GetComponent<Light>();
		}
		gameObject = GameObject.Find("PlayerSpawnArea");
		if (gameObject != null)
		{
			Player[] array2 = activePlayers;
			foreach (Player player2 in array2)
			{
				player2.transform.position = gameObject.transform.position;
			}
		}
		if (NextLevelLoader.InTierScene(string.Empty))
		{
			StartCoroutine(LevelGenerator.Generate(this));
		}
		else if (Application.loadedLevelName == "TitleScreen")
		{
			loadingScreen.FadeOut();
		}
		else
		{
			StartCoroutine(WaitForDependiesToLoad());
		}
	}

	private IEnumerator WaitForDependiesToLoad()
	{
		while (!coreDependenciesLoaded || !secondaryDependenciesLoaded || !effectsPoolsLoaded)
		{
			yield return null;
		}
		loadingScreen.FadeOut();
	}

	private void FixedUpdate()
	{

{
	ChaosStopwatch.Update(Time.time);
	Hazard.HandleGlobalTime();
	if (inGameScene)
	{
		HandleTimeUpdate(Time.fixedDeltaTime);
	}
}

private void Update()
{
	if (activePlayers.Length == 0 && !LoadingScreen.loading && characterSelectUI != null)
	{
		characterSelectUI.Activate();
	}
	if (queuedLevelName != string.Empty && curSkipLevelLoadFrame == 0)
	{
		LoadLevel(queuedLevelName);
	}
	else if (curSkipLevelLoadFrame > 0)
	{
		curSkipLevelLoadFrame--;
	}
	if (pauseQueued)
	{
		pauseQueued = false;
		GameUI.TogglePause();
		return;
	}
	if (loadingPauseQueued && !LoadingScreen.loading)
	{
		loadingPauseQueued = false;
		GameUI.TogglePause();
	}
	if ((!(levelSummary == null) && levelSummary.activated) || LoadingScreen.loading || !(currentLevelName != "Credits"))
	{
		return;
	}
	bool flag = false;
	bool flag2 = false;
	Player[] array = activePlayers;
	foreach (Player player in array)
	{
		flag = true;
		if (player.IsKeyboardInput)
		{
			flag2 = true;
		}
		if (GameUI.pauseMenu.paused)
		{
			if (!player.inputDevice.GetButtonUp("Menu") && !player.inputDevice.GetButtonUp("Cancel"))
			{
				continue;
			}
			if (!AllPlayersDead())
			{
				if (pausePressed)
				{
					pausePressed = false;
					return;
				}
				pauseQueued = true;
				pausePressed = false;
			}
			return;
		}
		if (player.inputDevice.GetButtonDown("Menu"))
		{
			if (AllPlayersDead())
			{
				return;
			}
			if (player.fsm.currentStateName != "Paused" || !player.IsKeyboardInput)
			{
				GameUI.TogglePause();
				pausePressed = true;
				return;
			}
		}
	}
	if (!flag || flag2 || AllPlayersDead())
	{
		return;
	}
	if (GameUI.pauseMenu.paused)
	{
		if (Input.GetKeyUp(KeyCode.Escape))
		{
			if (pausePressed)
			{
				pausePressed = false;
				return;
			}
			pauseQueued = true;
			pausePressed = false;
		}
	}
	else if (Input.GetKeyDown(KeyCode.Escape))
	{
		GameUI.TogglePause();
		pausePressed = true;
	}
}

private void HandleTimeUpdate(float givenDeltaTime)
{
	if (!pauseTimer)
	{
		levelTime += givenDeltaTime;
		totalTime += givenDeltaTime;
		timeSinceLastTimeSave += givenDeltaTime;
	}
}

public void InitDebugOptions()
{
	if (!Application.loadedLevelName.Contains("SFX") && (Input.GetKeyDown(KeyCode.Backspace) || InputController.GetAnyDeviceButtonDown("Debug") != null))
	{
		debugMenu.Toggle();
	}
	if (Input.GetKeyDown(KeyCode.Equals))
	{
		CameraController.originalCameraSize--;
	}
	if (Input.GetKeyDown(KeyCode.Minus))
	{
		CameraController.originalCameraSize++;
	}
	if (Input.GetKeyDown(KeyCode.Alpha1))
	{
		debugMenu.MaxDiff();
	}
	if (Input.GetKeyDown(KeyCode.Alpha2))
	{
		debugMenu.GodMode();
	}
	if (Input.GetKeyDown(KeyCode.Alpha3))
	{
		if (Time.timeScale == 1f)
		{
			Time.timeScale = 0.5f;
			GameUI.BroadcastNoticeMessage("50% Speed");
		}
		else if (Time.timeScale == 0.5f)
		{
			Time.timeScale = 0.25f;
			GameUI.BroadcastNoticeMessage("25% Speed");
		}
		else if (Time.timeScale == 0.25f)
		{
			Time.timeScale = 0.15f;
			GameUI.BroadcastNoticeMessage("15% Speed");
		}
