public static void PauseAllPlayers(bool state = true)
	if (state)
		Player[] array = activePlayers;
		foreach (Player player in array)
			if (!(player == null))
				player.lowerHUD.SetEquipMenuAllowed(givenStatus: false);
				player.fsm.defaultStateName = "Paused";
				if (!player.fsm.currentStateName.Contains("Dead"))
					player.fsm.ChangeState("Paused");
		return;
	Player[] array2 = activePlayers;
	foreach (Player player2 in array2)
		if (!(player2 == null))
			player2.lowerHUD.SetEquipMenuAllowed(givenStatus: true);
			player2.fsm.defaultStateName = "Idle";
			if (!player2.fsm.currentStateName.Contains("Dead"))
				player2.fsm.ChangeState("Idle");

public static bool PlayerIsDead()
	if (activePlayers.Length == 0)
		return false;
	Player[] array = activePlayers;
	foreach (Player player in array)
		if (player.fsm.currentStateName.Contains("Dead"))
			return true;
	return false;

public static bool AllPlayersDead()
	if (activePlayers.Length == 0)
		return false;
	Player[] array = activePlayers;
	foreach (Player player in array)
		if (!player.fsm.currentStateName.Contains("Dead") || player.inventory.GetResurrectItem() != null)
			return false;
	return true;

public static int GetAlivePlayerCount()
	int num = 0;
	Player[] array = activePlayers;
	foreach (Player player in array)
		if (!player.fsm.currentStateName.Contains("Dead"))
			num++;
	return num;

public static Vector3 GetPlayerPositionAverage()
	Vector3 zero = Vector3.zero;
	int num = 0;
	Player[] array = activePlayers;
	foreach (Player player in array)
		if (!player.fsm.currentStateName.Contains("Dead"))
			num++;
			zero += player.cameraLockTransform.position;
	if (bosses.Count > 0)
		num *= 2;
		zero *= 2f;
		foreach (GameObject boss in bosses)
			if (!(boss == null))
				num++;
				zero += boss.transform.position;
	return (num != 0) ? (zero / num) : Vector3.zero;

private void HandleLostFocus(bool hasFocus)
	if (activePlayers.Length == 0)
		return;
	if (hasFocus && loadingPauseQueued)
		loadingPauseQueued = false;
	else if (!hasFocus && !GameUI.pauseMenu.paused)
		if (LoadingScreen.loading)
			loadingPauseQueued = true;
			UnityEngine.Debug.Log("loading queued");
		else
			GameUI.TogglePause();

