using UnityEngine;
public class NextLevelLoader : MonoBehaviour
{
	public string nextLevelName;
	public bool showLevelSummary;
	public ExitPortal exitPortal;
	private bool portalEntered;
	public bool forceTriggerExit;
	private Player player;
	private float overheadPromptHeight = 2.5f;
	private OverheadPrompt overHeadPrompt;
	public OverheadPrompt CurrentOverheadPrompt
	{
		get
		{
			return overHeadPrompt ?? (overHeadPrompt = PoolManager.GetPoolItem<OverheadPrompt>());
		}
		set
		{
			if (value == null && overHeadPrompt != null)
			{
				overHeadPrompt.HidePrompt(string.Empty);
				overHeadPrompt = null;
			}
		}
	}
	public void Awake()
	{
		if (transform.parent != null)
		{
			exitPortal = transform.parent.GetComponent<ExitPortal>();
		}
	}
	public virtual void Update()
	{
		if (this.player == null || portalEntered)
		{
			return;
		}
		if (this.player.IsDead || Vector2.Distance(this.player.transform.position, transform.position) > 2f)
		{
			this.player = null;
			CurrentOverheadPrompt = null;
			if (exitPortal != null)
			{
				exitPortal.Deactivate();
			}
		}
		else if (this.player.IsAvailable && this.player.inputDevice.GetButtonDown("Interact"))
		{
			CurrentOverheadPrompt = null;
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				player.transform.position = transform.position;
				player.fall.ignoreFall.AddMod(new BoolVarStatMod("LevelLoad", newModValue: true, 0));
				player.hurtBoxObj.SetActive(value: false);
			}
			if (exitPortal != null)
			{
				exitPortal.Deactivate();
				exitPortal.Close();
			}
			else
			{
				LoadNextLevel();
			}
			portalEntered = true;
		}
	}
	public virtual void OnTriggerStay2D(Collider2D col)
	{
		if (!forceTriggerExit && !portalEntered && player == null)
		{
			player = Player.CheckForPlayer(col);
			if (player != null && player.IsAvailable)
			{
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
				exitPortal.Prepare();
			}
		}
	}
	public virtual void OnTriggerExit2D(Collider2D col)
	{
		bool flag = Player.CheckForPlayer(col);
		if (forceTriggerExit && flag)
		{
			forceTriggerExit = false;
		}
		if (flag && player != null && player.IsAvailable)
		{
			CurrentOverheadPrompt = null;
			player = null;
			if (exitPortal != null)
			{
				exitPortal.Deactivate();
			}
		}
	}
	public static bool InBossScene(string levelName = "")
	{
		if (levelName == string.Empty)
		{
			levelName = Application.loadedLevelName;
		}
		if (levelName == "FinalBossLevel")
		{
			return true;
		}
		foreach (string value in GameController.bossLevelNameDict.Values)
		{
			if (levelName == value)
			{
				return true;
			}
		}
		return false;
	}
	public static bool InTierScene(string levelName = "")
	{
		if (levelName == string.Empty)
		{
			levelName = Application.loadedLevelName;
		}
		return GameController.levelNameList.Contains(levelName);
	}
	public static string GetCurrentTierScene(int tierCount = -1)
	{
		if (tierCount == -1)
		{
			tierCount = GameController.tierCount;
		}
		tierCount = Mathf.Clamp(tierCount, 0, GameController.MaxTierCount);
		return GameController.levelNameList[tierCount];
	}
	public static void SetLevelInfo(string nextLevelName = "")
	{
		string empty = string.Empty;
		ElementType elementType = ElementType.Neutral;
		switch (nextLevelName)
		{
		case "Forest":
			empty = "ForestTileSet";
			elementType = ElementType.Earth;
			break;
		case "Earth":
			empty = "EarthTileSet";
			elementType = ElementType.Earth;
			break;
		case "Ice":
			empty = "IceTileSet";
			elementType = ElementType.Water;
			break;
		case "Fire":
			empty = "FireTileSet";
			elementType = ElementType.Fire;
			break;
		case "Air":
			empty = "AirTileSet";
			elementType = ElementType.Air;
			break;
		case "Lightning":
			empty = "LightningTileSet";
			elementType = ElementType.Lightning;
			break;
		case "PlayerRoom":
			empty = "HomeTileSet";
			elementType = ElementType.Neutral;
			break;
		default:
			empty = "CastleBaseTileSet";
			elementType = ElementType.Neutral;
			break;
		}
		Level.tileSetName = empty;
		Level.element = elementType;
	}
	public virtual void LoadNextLevel()
	{
		if (nextLevelName == string.Empty)
		{
			nextLevelName = GetCurrentTierScene();
			if (Level.isBossRushMode)
			{
				RunData.AddTimeStamp();
			}
			if (InTierScene(string.Empty))
			{
				if (GameController.stageCount > ((!Level.isBossRushMode) ? GameController.stagesPerTier : GameController.stagesPerRush))
				{
					nextLevelName = GameController.bossLevelNameDict[Application.loadedLevelName];
				}
			}
			else if (Application.loadedLevelName.Contains("BossLevel"))
			{
				GameController.stageCount = 0;
				GameController.tierCount++;
				if (Level.isBossRushMode)
				{
					switch (GameController.tierCount)
					{
					case 5:
						nextLevelName = "FinalBossLevel";
						break;
					case 6:
						nextLevelName = "TitleScreen";
						break;
					default:
						nextLevelName = GetCurrentTierScene();
						break;
					}
				}
				else
				{
					switch (GameController.tierCount)
					{
					case 3:
						nextLevelName = "FinalBossLevel";
						break;
					case 4:
						nextLevelName = "Ending";
						break;
					default:
						nextLevelName = GetCurrentTierScene();
						break;
					}
				}
			}
		}
		if (showLevelSummary)
		{
			GameController.levelSummary.Activate(nextLevelName);
		}
		else
		{
			GameController.LoadLevel(nextLevelName);
		}
	}
