using System.Collections.Generic;
public class PlayerRunData
{
	public int playerID = -1;
	public int winTokenCount;
	public bool pvpWon;
	public string startSpellBasic = string.Empty;
	public string startSpellDash = string.Empty;
	public string startSpellStandard = string.Empty;
	public string startSpellSignature = string.Empty;
	public string startItem = string.Empty;
	public string startOutfit = string.Empty;
	public bool outFitEnhanced;
	public List<string> endSpellList = new List<string>();
	public string endSpellStock = string.Empty;
	public List<string> endRelicList = new List<string>();
	private Player.SkillState tempSkillState;
	public PlayerRunData(Player givenPlayer = null)
	{
		Reset();
		if (givenPlayer != null)
		{
			Init(givenPlayer);
		}
	}
	public void Reset()
	{
		playerID = -1;
		winTokenCount = 0;
		startSpellBasic = string.Empty;
		startSpellDash = string.Empty;
		startSpellStandard = string.Empty;
		startSpellSignature = string.Empty;
		startItem = string.Empty;
		startOutfit = string.Empty;
		outFitEnhanced = false;
		endSpellList.Clear();
		endSpellStock = string.Empty;
		endRelicList.Clear();
	}
	public void Init(Player givenPlayer)
	{
		playerID = givenPlayer.playerID;
		winTokenCount = 0;
		tempSkillState = givenPlayer.GetBasicSkill();
		if (tempSkillState != null)
		{
			startSpellBasic = tempSkillState.skillID;
		}
		tempSkillState = givenPlayer.GetDashSkill();
		if (tempSkillState != null)
		{
			startSpellDash = tempSkillState.skillID;
		}
		tempSkillState = givenPlayer.GetAnyStandardSkill();
		if (tempSkillState != null)
		{
			startSpellStandard = tempSkillState.skillID;
		}
		tempSkillState = givenPlayer.GetSignatureSkill();
		if (tempSkillState != null)
		{
			startSpellSignature = tempSkillState.skillID;
		}
		if (givenPlayer.inventory != null && givenPlayer.inventory.Count > 0)
		{
			startItem = givenPlayer.inventory.GetItemIDList()[0];
		}
		else
		{
			startItem = givenPlayer.designatedItemID;
		}
		startOutfit = givenPlayer.outfitID;
		outFitEnhanced = false;
	}
	public void End(Player givenPlayer)
	{
		endSpellList.Clear();
		Player.SkillState[] assignedSkills = givenPlayer.assignedSkills;
		foreach (Player.SkillState skillState in assignedSkills)
		{
			if (skillState != null)
			{
				endSpellList.Add(skillState.skillID);
			}
		}
		endSpellList.Remove(startSpellBasic);
		endSpellList.Remove(startSpellDash);
		endSpellList.Remove(startSpellStandard);
		endSpellList.Remove(startSpellSignature);
		endSpellStock = string.Empty;
		if (givenPlayer.stockSkill != null && givenPlayer.stockSkill.skillID != startSpellStandard)
		{
			endSpellStock = givenPlayer.stockSkill.skillID;
		}
		endRelicList.Clear();
		foreach (string itemID in givenPlayer.inventory.GetItemIDList())
		{
			endRelicList.Add(itemID);
		}
		endRelicList.Remove(startItem);
	}
}
