	{
		SetRushStatus(givenStatus: false);
	}
	private void SetRushStatus(bool givenStatus)
	{
		Level.isBossRushMode = givenStatus;
		if (givenStatus)
		{
			EnemyGlobalStatManager.useDiffScaling = givenStatus;
		}
		Level.removeAllPits = givenStatus;
		Decorator[] array = Decorator.TileSetDecorators.Values.ToArray();
		if (givenStatus)
		{
			for (int i = 0; i < array.Length; i++)
			{
				for (int j = 0; j < array[i].globalDecorations0.Count; j++)
				{
					if (array[i].globalDecorations0[j] is PitDecoration)
					{
						array[i].globalDecorations0[j].spawnChance = 0f;
					}
				}
			}
			return;
		}
		for (int k = 0; k < array.Length; k++)
		{
			for (int l = 0; l < array[k].globalDecorations0.Count; l++)
			{
				if (array[k].globalDecorations0[l] is PitDecoration)
				{
					array[k].globalDecorations0[l].spawnChance = HallwayPitDecoration.defaultPitSpawnChance;
				}
			}
		}
	}
	public override void OnLevelWasLoaded()
	{
		base.OnLevelWasLoaded();
		if (GameController.prevLevelName != "Hub")
		{
			return;
		}
		if (removeIDList == null)
		{
			removeIDList = new List<string>();
		}
		else
		{
			removeIDList.Clear();
		}
		if (GameController.prevLevelName == "Hub")
		{
			Player.goldWallet.balance = 0;
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				foreach (Item value in player.inventory.itemDict.Values)
				{
					if (value != null && value.isCursed)
					{
						removeIDList.Add(value.ID);
					}
				}
				for (int j = 0; j < removeIDList.Count; j++)
				{
					player.inventory.RemoveItem(removeIDList[j], forceOverride: true);
				}
				player.health.RestoreHealth(9999, showDisplayText: false, playSound: false, fullyRestoreHealth: true, useHealEnterEvent: false);
			}
		}
		useOnLevelWasLoaded = false;
	}
