using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
public class ChaosLogger : MonoBehaviour
{
	private string logFullPath;
	private FileStream fileStream;
	private StreamWriter streamWriter;
	private string logID;
	private Dictionary<string, bool> errorLog;
	private static ChaosLogger Instance { get; set; }
	private void Awake()
	{
		if (Instance != null)
		{
			UnityEngine.Object.DestroyImmediate(gameObject);
			return;
		}
		Instance = this;
		UnityEngine.Object.DontDestroyOnLoad(gameObject);
		logID = (DateTime.UtcNow.Subtract(new DateTime(1970, 1, 1)).Ticks / 10000000).ToString();
		logFullPath = Application.persistentDataPath + "/error-" + logID + ".log";
		errorLog = new Dictionary<string, bool>();
	}
	private void OnEnable()
	{
		Application.logMessageReceived += HandleLog;
	}
	private void OnDisable()
	{
		Application.logMessageReceived -= HandleLog;
		if (fileStream != null)
		{
			fileStream.Close();
		}
		if (streamWriter != null)
		{
			streamWriter.Close();
		}
	}
	private void InitLogFile()
	{
		if (fileStream == null || streamWriter == null)
		{
			fileStream = new FileStream(logFullPath, FileMode.Append);
			streamWriter = new StreamWriter(fileStream);
		}
	}
	private void RotateLogs()
	{
		DirectoryInfo directoryInfo = new DirectoryInfo(Application.persistentDataPath);
		FileInfo[] files = directoryInfo.GetFiles("error-*.log");
		if (files.Length > 8)
		{
			int num = files.Length - 7;
			for (int i = 0; i < num; i++)
			{
				files[i].Delete();
			}
		}
	}
	private void HandleLog(string logString, string stackTrace, LogType type)
	{
		try
		{
			if (type == LogType.Error || type == LogType.Exception)
			{
				RotateLogs();
				string key = type.ToString() + logString.Substring(0, 20) + stackTrace.Substring(0, 20);
				if (!errorLog.ContainsKey(key))
				{
					errorLog[key] = true;
					InitLogFile();
					streamWriter.Write("------------------------\r\n" + logString + "\r\n\r\n" + stackTrace.Replace("\n", "\r\n") + "\r\n\r\n");
					streamWriter.Flush();
				}
			}
		}
		catch (Exception)
		{
		}
	}
}
