		{
			if (Level.levelContainer != null)
			{
				worldTransform = Level.levelContainer.transform;
				worldTileGrid = Level.tileGrid;
			}
			else
			{
				GameObject[] array = GameObject.FindGameObjectsWithTag("Room");
				for (int i = 0; i < array.Length; i++)
				{
					Room component = array[i].GetComponent<Room>();
					if (!(component == null) && component.gameObject.activeSelf && component.enabled)
					{
						worldTransform = array[i].transform;
						worldTileGrid = component.tileGrid;
						break;
					}
				}
			}
			worldInfoInitialized = true;
		}
		if (worldTransform == null || worldTileGrid == null)
		{
			lastTileRow = -1;
			lastTileCol = -1;
			return;
		}
		int num = (int)Mathf.Floor(worldTransform.position.y - transform.position.y);
		int num2 = -(int)Mathf.Floor(worldTransform.position.x - transform.position.x) - 1;
		if (lastTileRow < 0 || lastTileCol < 0 || num != lastTileRow || num2 != lastTileCol)
		{
			lastTileRow = num;
			lastTileCol = num2;
			HandleTerrainInteraction();
		}
	}
