	public FacingDirection FaceTarget(Vector3 targetPosition, int validAxisCount = 4, bool useHurtBox = false)
	{
		Vector3 vector = ((!useHurtBox) ? transform.position : hurtBoxTransform.position);
		Vector2 vector2 = targetPosition - vector;
		if (Mathf.Abs(vector2.x) > Mathf.Abs(vector2.y) || validAxisCount == 2)
		{
			isFacingRight = targetPosition.x >= vector.x;
			facingDirection = (isFacingRight ? FacingDirection.Right : FacingDirection.Left);
		}
		else
		{
			isFacingRight = true;
			facingDirection = ((!(vector2.y > 0f)) ? FacingDirection.Down : FacingDirection.Up);
		}
		return facingDirection;
	}
