	public bool PlayAnimOnFaceDirChange(string animName, Vector3 targetPosition, int validAxisCount = 4, bool appendFacingDirection = true, float animStartTime = 0f)
	{
		previousFacingDirection = facingDirection;
		FaceTarget(targetPosition, validAxisCount);
		if (previousFacingDirection != facingDirection)
		{
			anim.PlayDirectional((!appendFacingDirection) ? animName : (animName + facingDirection), -1, animStartTime);
			return true;
		}
		return false;
