	public int FindAndTraversePath(Dictionary<Vector2, Node> map, Vector2 start, Vector2 end, float boundRadius = 1f, string animationName = "", bool appendFacingDirection = true, int validAxisCount = 2, bool startNew = false)
	{
		if (movement == null)
		{
			return -1;
		}
		if (startNew || foundPath == null || pathIndex > foundPath.pathVecList.Count - 1)
		{
			foundPath = Pathfinder.GetPath(map, start, end, lineOfSightLayerMask);
			pathIndex = 0;
			if (foundPath == null)
			{
				return -1;
			}
		}
		if (animationName != string.Empty)
		{
			PlayAnimOnFaceDirChange(animationName, foundPath.pathVecList[pathIndex], validAxisCount, appendFacingDirection);
		}
		if (movement.MoveToTarget(foundPath.pathVecList[pathIndex], boundRadius))
		{
			if (pathIndex < foundPath.pathVecList.Count - 1)
			{
				pathIndex++;
				return 0;
			}
			foundPath = null;
			return 1;
		}
		return 0;
	}
	public static bool IsPathObstructed(Vector2 origin, Vector2 dir, float dist = 1f, int layerMask = -1)
	{
		if (layerMask == -1)
		{
			layerMask = ChaosCollisions.layerAll;
		}
		return Physics2D.Raycast(origin, dir, dist, layerMask).collider != null;
	}
	public static Vector2 GetAvailableNearbyLocation(Vector2 origin, bool excludeOrigin = false, bool randomize = true)
	{
		List<Vector2> availableNearbyLocations = GetAvailableNearbyLocations(origin, excludeOrigin);
		Vector2 result;
		if (availableNearbyLocations.Count != 0)
		{
			result = ((!randomize) ? availableNearbyLocations[0] : availableNearbyLocations[UnityEngine.Random.Range(0, availableNearbyLocations.Count)]);
		}
		else
		{
			result = Vector2.zero;
		}
		return result;
	}
	public static List<Vector2> GetAvailableNearbyLocations(Vector2 origin, bool excludeOrigin = false)
	{
		List<Vector2> list = new List<Vector2>();
		if (!excludeOrigin && Globals.CheckCircle(origin, 0.25f, ChaosCollisions.layerAll))
		{
			list.Add(origin);
		}
		Vector2[] vector2DirectionalArray = Globals.Vector2DirectionalArray;
		foreach (Vector2 vector in vector2DirectionalArray)
		{
			if (Globals.CheckCircle(origin + vector, 0.25f, ChaosCollisions.layerAll))
			{
				list.Add(vector + origin);
			}
		}
		return list;
	}
