	public bool destroyAfterRandomize = true;
	public bool randomizeOnStart;
	public bool useFacingDirection;
	public float xOffset;
	private bool xOffsetApplied;
	public void Awake()
	{
		if (!randomizeOnStart)
		{
			DoRandomize();
		}
	}
	public override void Start()
	{
		base.Start();
		if (randomizeOnStart)
		{
			DoRandomize();
		}
	}
	public void DoRandomize()
	{
		if (useFacingDirection)
		{
			RandomizeFacingDir();
		}
		else
		{
			RandomizeLocalScale();
		}
		Object.Destroy(this);
	}
	public void RandomizeFacingDir()
	{
		if (parentFSM != null && !(entityScript == null))
		{
			entityScript.facingDirection = ((!((double)Random.value < 0.5)) ? FacingDirection.Right : FacingDirection.Left);
		}
	}
	public void RandomizeLocalScale()
	{
		int num = ((!((double)Random.value < 0.5)) ? 1 : (-1));
		Transform transform = null;
		transform = ((!(entityScript != null)) ? base.transform : entityScript.transform);
		transform.localScale = new Vector3(transform.localScale.x * (float)num, transform.localScale.y, transform.localScale.z);
		if ((float)num < 0f)
		{
			transform.position = new Vector3(transform.position.x + xOffset, transform.position.y, transform.position.z);
			xOffsetApplied = true;
			if (entityScript != null)
			{
				entityScript.facingDirection = FacingDirection.Left;
				entityScript.isFacingRight = false;
			}
		}
		else if (xOffsetApplied)
		{
			transform.position = new Vector3(transform.position.x - xOffset, transform.position.y, transform.position.z);
			xOffsetApplied = false;
		}
	}
