			return;
		}
		modifiedStatDataList = GetAllStatData("Skills", givenCategory);
		if (addMod)
		{
			for (int num = modifiedStatDataList.Count - 1; num > -1; num--)
			{
				modifiedStatData = modifiedStatDataList[num];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					foreach (KeyValuePair<string, NumVarStatMod> item in givenDict)
					{
						modifiedStatData.AddMod(item.Key, item.Value);
					}
				}
			}
		}
		else
		{
			for (int num2 = modifiedStatDataList.Count - 1; num2 > -1; num2--)
			{
				modifiedStatData = modifiedStatDataList[num2];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
