	public static AnimFrameData Generate(AnimFrameDataOverride animDataOverride, AnimFrameData frameData)
	{
		AnimFrameData animFrameData = new AnimFrameData(frameData);
		animDataOverride.overrideFrameCount = 0;
		foreach (KeyValuePair<string, int> @override in animDataOverride.overrides)
		{
			string key = @override.Key;
			int value = @override.Value;
			if (value == 0)
			{
				animFrameData.Remove(key);
			}
			animDataOverride.overrideFrameCount += value;
		}
		foreach (KeyValuePair<string, AnimSection> section in animFrameData.sections)
		{
			AnimSection value2 = section.Value;
			int num = value2.endFrame - value2.startFrame + 1;
			value2.speed = (float)num / (float)animDataOverride.overrides[value2.name];
		}
		return animFrameData;
	}
