	public virtual void SetType()
	{
	}
	public virtual void HandleSetSortOrder()
	{
	}
	public virtual void Awake()
	{
		if (sortingLayer == string.Empty)
		{
			sortingLayer = "Default";
			Debug.Log("Sorting Layer not set for: " + ((!(transform.parent == null)) ? (transform.parent.gameObject.name + "/") : string.Empty) + gameObject.name + ". Setting to Default.");
		}
		SetType();
		CreateList();
		baseTransform = transform;
		iList = GetComponentsInChildren(type).ToList();
		childSorterList = GetComponentsInChildren<SortGenericLayer>().ToList();
		childSorterList.Remove(this);
	}
	public new virtual void Start()
	{
		for (int i = 0; i < childSorterList.Count; i++)
		{
			SortGenericLayer sortGenericLayer = childSorterList[i];
			if (sortGenericLayer.GetType() != sorterType || sortGenericLayer.sortingLayer != sortingLayer)
			{
				childSorterList.RemoveAt(i);
				i--;
				continue;
			}
			for (int j = 0; j < sortGenericLayer.iList.Count; j++)
			{
				iList.Remove(sortGenericLayer.iList[j]);
			}
			if (sortGenericLayer.sortBySpriteTransform)
			{
				childSorterList.RemoveAt(i);
				i--;
			}
		}
		SetChildBaseTransforms(baseTransform);
	}
	public virtual void Update()
	{
		if (sortOnlyOnce)
		{
			HandleSetSortOrder();
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			HandleSetSortOrder();
		}
	}
	protected void CreateList()
	{
		iList = (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(type));
	}
	protected int GetSortingOrder(float yPosition)
	{
		return (int)((float)(1024 + yLayerOffset) + -16f * (yValueOffset + ((!sortBySpriteTransform) ? baseTransform.position.y : yPosition)));
	}
	protected void SetChildBaseTransforms(Transform givenTrans)
	{
		childSorterList.Remove(this);
		foreach (SortGenericLayer childSorter in childSorterList)
		{
			childSorter.baseTransform = givenTrans;
			childSorter.SetChildBaseTransforms(givenTrans);
		}
	}
