	public void Activate(string nextLevel)
	{
		if (GameUI.pauseMenu != null && GameUI.pauseMenu.paused)
		{
			GameUI.TogglePause();
		}
		TimeScaleController.Pause(status: true);
		nextLevelName = nextLevel;
		SetValues(GameController.levelTime, Minimap.RevealedPercentage, GameController.levelGold, GameController.levelPlat);
		activated = true;
		gameObject.SetActive(value: true);
		GameController.PauseAllPlayers();
		continueImage.sprite = GameUI.GetInputSprite(GameController.activePlayers[0].inputDevice.inputScheme);
		if (Application.loadedLevelName.Contains("Boss"))
		{
			anim.Play("IdleLevel4");
			return;
		}
		switch (GameController.stageCount)
		{
		case 1:
			anim.Play("Level1To2");
			break;
		case 2:
			anim.Play("Level2To3");
			break;
		case 3:
			anim.Play("Level3To4");
			break;
		default:
			anim.Play("Idle");
			break;
		}
	}
	private void PlayIdleAnim()
	{
		switch (GameController.stageCount)
		{
		case 1:
			anim.Play("IdleLevel2");
			break;
		case 2:
			anim.Play("IdleLevel3");
			break;
		case 3:
			anim.Play("IdleLevel4");
			break;
		default:
			anim.Play("Idle");
			break;
		}
	}
	protected override void Update()
	{
		base.Update();
		if (!activated)
		{
			return;
		}
		if (!frameSkipped)
		{
			frameSkipped = true;
			return;
		}
		if (buttonDelayTimer > 0f)
		{
			buttonDelayTimer -= deltaTime;
		}
		else if (InputController.GetAnyDeviceButtonUp("Confirm") != null)
		{
			Deactivate();
			buttonDelayTimer = buttonDelay;
		}
		if (!GameController.coopOn || GameController.activePlayers.Length != 2 || crownAnimPlayed)
		{
			return;
		}
		if (crownDelayTimer > 0f)
		{
			crownDelayTimer -= deltaTime;
			return;
		}
		if (player1Wins == 1)
		{
			playerStatRefs[0].crownAnim.Play("CrownSpawn");
		}
		else if (player1Wins == -1)
		{
			playerStatRefs[1].crownAnim.Play("CrownSpawn");
		}
		else
		{
			playerStatRefs[0].crownAnim.Play("CrownSpawn");
			playerStatRefs[1].crownAnim.Play("CrownSpawn");
		}
		crownAnimPlayed = true;
	}
	private void Deactivate()
	{
		TimeScaleController.Pause(status: false);
		Reset();
		GameController.LoadLevel(nextLevelName);
	}
	private void DetermineWinner(int winnerValue)
	{
		switch (winnerValue)
		{
		case 1:
			RunData.GiveWinToken(0);
			break;
		case -1:
			RunData.GiveWinToken(1);
			break;
		default:
			RunData.GiveWinToken(0);
			RunData.GiveWinToken(1);
			break;
		}
	}
	private void SetValues(float givenTime, string givenMap, int givenGold, int givenPlat)
	{
		timeValue.text = Globals.TimeToString(givenTime);
		mapValue.text = ((!GameController.minimap.IsActive()) ? "--" : givenMap);
		goldValue.text = givenGold.ToString();
		platValue.text = givenPlat.ToString();
		showPvpStat = Application.loadedLevelName.Contains("BossLevel") && GameController.coopOn;
		pvpStatsObj.SetActive(showPvpStat);
		if (showPvpStat)
		{
			pvpWinnerID = RunData.GetPvpWinnerID();
		}
		int[] array = new int[2];
		int[] array2 = new int[2];
		int[] array3 = new int[2];
		int[] array4 = new int[2];
		int[] array5 = new int[2];
		int num = GameController.activePlayers.Length;
		int num2 = 0;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			num2 += player.stats.GetStatValue(PlayerEndStats.Stat.Spent);
		}
		if (num2 == 0)
		{
			num2 = 1;
		}
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			currentPlayerID = player2.playerID;
			array[currentPlayerID] = player2.stats.GetStatValue(PlayerEndStats.Stat.Basic) + player2.stats.GetStatValue(PlayerEndStats.Stat.Spell);
			array2[currentPlayerID] = player2.stats.GetStatValue(PlayerEndStats.Stat.Enemies) * enemiesDefeatedMulti;
			array3[currentPlayerID] = Mathf.Min(0, Mathf.CeilToInt((float)healthBonusAmount * (1f - (float)player2.stats.GetStatValue(PlayerEndStats.Stat.Taken) / player2.health.healthStat.ModifiedValue)));
			array4[currentPlayerID] = Mathf.CeilToInt((float)goldBonusAmount * (1f - (float)player2.stats.GetStatValue(PlayerEndStats.Stat.Spent) / (float)num2));
			array5[currentPlayerID] = Mathf.Max(0, array[currentPlayerID] + array2[currentPlayerID] + array3[currentPlayerID] + array4[currentPlayerID] + ((showPvpStat && pvpWinnerID == currentPlayerID) ? pvpPointAmount : 0));
		}
		if (GameController.coopOn && num == 2)
		{
			player1Wins = 0;
			if (array5[0] < array5[1])
			{
				player1Wins = -1;
			}
			else if (array5[0] > array5[1])
			{
				player1Wins = 1;
			}
			DetermineWinner(player1Wins);
			p2StatsObj.SetActive(value: true);
		}
		else
		{
			p2StatsObj.SetActive(value: false);
		}
		for (int k = 0; k < num; k++)
		{
			currentPlayer = GameController.activePlayers[k];
			currentPlayerID = currentPlayer.playerID;
			playerStatRefs[currentPlayerID].buildName.text = TextManager.GetUIText("playerName-" + ((currentPlayerID != 0) ? "1" : "0"));
			playerStatRefs[currentPlayerID].baseStat.text = currentPlayer.stats.GetStatValue(PlayerEndStats.Stat.Basic) + "\n" + currentPlayer.stats.GetStatValue(PlayerEndStats.Stat.Spell) + "\n" + array2[currentPlayerID] + " (" + currentPlayer.stats.GetStatValue(PlayerEndStats.Stat.Enemies) + ")\n" + array3[currentPlayerID] + " (" + currentPlayer.stats.GetStatValue(PlayerEndStats.Stat.Taken) + ")\n" + array4[currentPlayerID] + " (" + currentPlayer.stats.GetStatValue(PlayerEndStats.Stat.Spent) + ")";
			Text pvpStat = playerStatRefs[currentPlayerID].pvpStat;
			string text;
			if (showPvpStat)
			{
				text = ((pvpWinnerID != currentPlayerID) ? "--" : pvpPointAmount.ToString());
			}
			else
			{
				text = string.Empty;
			}
			pvpStat.text = text;
			playerStatRefs[currentPlayerID].totalStat.text = array5[currentPlayerID].ToString();
