	public virtual void OnTriggerEnter2D(Collider2D col)
	{
		if (!(col.gameObject.tag == "Player") || (!(col.gameObject.name == "AllyFloorContact") && !(col.gameObject.name == "IgnoreFloorContact")))
		{
			return;
		}
		triggeredPosition = col.transform.position;
		if (!triggerCollider.enabled)
		{
			return;
		}
		triggerCollider.enabled = false;
		if (triggerSFX != string.Empty)
		{
			SoundManager.PlayAudio(triggerSFX);
		}
		if (useTriggerWall)
		{
			triggerWall.SetActive(value: true);
		}
		playerStartHealthValues = new int[GameController.activePlayers.Length];
		int playerID = col.transform.parent.gameObject.GetComponent<Player>().playerID;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player.playerID != playerID && !player.fsm.currentStateName.Contains("Dead") && !player.TeleportToPartner(playerID, showSpawnPortal: true, excludeOrigin: true))
			{
				player.TeleportToPartner(playerID);
			}
			player.lastCheckpoint = bossSpawnPosition + Vector3.down;
			playerStartHealthValues[player.playerID] = player.health.CurrentHealthValue;
		}
		if (DebugMenu.godModeOn)
		{
			playBossDialog = false;
		}
		StartCoroutine(BossIntro());
	}
	public virtual void Update()
	{
		if (!bossSpawned || exitSpawned || (!(boss == null) && !boss.fsm.currentStateName.Contains("Dead")))
		{
			return;
		}
		int num = 0;
		int num2 = 0;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			num2++;
			if ((player.fsm.currentStateName.Contains("Dead") || player.health.CurrentHealthValue <= 0) && player.inventory.GetResurrectItem() == null)
			{
				num++;
			}
		}
		if (!bossDefeated && num != num2)
		{
			bossDefeated = true;
			Player[] activePlayers2 = GameController.activePlayers;
			foreach (Player player2 in activePlayers2)
			{
				player2.dotManager.RemoveAll();
			}
			StartCoroutine(BossOutro());
		}
		else if (bossDespawned && !HandlePvP() && !exitSpawned)
		{
			exitSpawned = true;
			StartCoroutine(ActivateExitPortal());
		}
	}
	public virtual bool HandlePvP()
	{
		if (Level.isBossRushMode || !GameController.coopOn || (pvpAttempted && !pvpActive))
		{
			return false;
		}
		if (!pvpAttempted && Inventory.EitherPlayerHasItem(BuffWithFriendship.staticID))
		{
			return false;
		}
		alivePlayerCount = 0;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!player.fsm.currentStateName.Contains("Dead"))
			{
				alivePlayerCount++;
			}
		}
		if (!pvpAttempted)
		{
			pvpAttempted = true;
			if (alivePlayerCount > 1)
			{
				playerOriginalHealthAmounts = new Dictionary<int, int>();
				Player[] activePlayers2 = GameController.activePlayers;
				foreach (Player player2 in activePlayers2)
				{
					playerOriginalHealthAmounts[player2.playerID] = (int)player2.health.healthStat.CurrentValue;
				}
				StartCoroutine(StartPvP());
				pvpStarted = true;
				pvpActive = true;
			}
			else
			{
				RunData.SetPvpWinner(-1);
			}
		}
		else if (pvpActive && alivePlayerCount < 2)
		{
			pvpActive = false;
			TimeScaleController.StandardFreezeIntoEaseOutTimeScale();
			Player[] activePlayers3 = GameController.activePlayers;
			foreach (Player player3 in activePlayers3)
			{
				if (!player3.fsm.currentStateName.Contains("Dead"))
				{
					RunData.SetPvpWinner(player3.playerID);
					break;
				}
			}
		}
		return pvpActive;
	}
	public virtual IEnumerator BossIntro()
	{
		CameraController camController = GameController.cameraController;
		Vector3 originalCameraPosition = ((!(cameraLockPosition == Vector3.zero)) ? cameraLockPosition : camController.transform.position);
		bool horiOnly = ((!overrideCameraLocks) ? camController.HoriMoveOnly : (!overrideHoriLockValue));
		bool vertOnly = ((!overrideCameraLocks) ? camController.VertMoveOnly : (!overrideVertLockValue));
		if (playBossDialog)
		{
			GameController.PauseAllPlayers();
			Vector3? targetLoc = bossSpawnPosition + bossCameraOffset;
			camController.OverrideAndMoveCameraToLocation(null, targetLoc, 2f, followPlayer: false, setLocks: true, vertLockStatus: true, horiLockStatus: true);
			yield return Globals.waitForOne;
		}
		boss = Object.Instantiate(bossPrefab, bossSpawnPosition, Quaternion.identity).GetComponent<Boss>();
		boss.health.invulnerable = true;
		boss.health.showDamageNumbers = false;
		yield return null;
		if (playBossDialog)
		{
			yield return new WaitForSeconds(bossSpawnDelay);
			while (!GameUI.dialogManager.HandleDialog(bossIntroDialogID, resetOnExit: true, unpauseOnComplete: false, 0.5f))
			{
				yield return null;
			}
			boss.ExitIntro();
			yield return Globals.waitForHalf;
			Vector3? targetLoc = originalCameraPosition;
			camController.OverrideAndMoveCameraToLocation(null, targetLoc, 2f, followPlayer: false, setLocks: true, horiOnly, vertOnly);
			yield return Globals.waitForOne;
			while (camController.overrideCameraUpdate)
			{
				yield return null;
			}
			GameController.PauseAllPlayers(state: false);
		}
		else
		{
			yield return Globals.waitForOne;
			boss.ExitIntro();
			Vector3? targetLoc = originalCameraPosition;
			camController.OverrideAndMoveCameraToLocation(null, targetLoc, 0.25f, !horiOnly && !vertOnly, setLocks: true, horiOnly, vertOnly);
			yield return Globals.waitForHalf;
		}
		yield return null;
		boss.fsm.ChangeState(boss.bossReadyState.name);
		boss.health.invulnerable = false;
		boss.health.showDamageNumbers = true;
		bossSpawned = true;
		SoundManager.PlayBGM("Boss");
	}
	public virtual IEnumerator BossOutro()
	{
		boss.health.invulnerable = true;
		boss.health.showDamageNumbers = false;
		CheckForPerfectFight();
		GameController.stageTitleUI.AnnounceVictory();
		yield return Globals.waitForOne;
		SoundManager.PlayBGM(string.Empty);
		if (playBossDialog)
		{
			while (!GameUI.dialogManager.HandleDialog(bossVictoryDialogID, resetOnExit: true, unpauseOnComplete: true, 0.5f))
			{
				yield return null;
			}
		}
		boss.fsm.ChangeState("Outro");
		while (boss != null)
		{
			yield return null;
		}
		bossDespawned = true;
	}
