	private void SetStageLayout()
	{
		if (availableRoomDict == null)
		{
			availableRoomDict = new Dictionary<string, GameObject>();
			GameObject gameObject = GameObject.Find("PvPRooms").gameObject;
			Room[] componentsInChildren = gameObject.GetComponentsInChildren<Room>();
			foreach (Room room in componentsInChildren)
			{
				availableRoomDict.Add(room.gameObject.name, room.gameObject);
			}
		}
		if (!availableRoomDict.ContainsKey(selectedRoomName))
		{
			selectedRoomName = "DefaultRoom";
		}
		forceEmpowerDrop = selectedRoomName.Contains("Lightning");
		applyAirRoomBuffs = selectedRoomName.Contains("Air");
		applyEarthRoomBuffs = selectedRoomName.Contains("Earth");
		applyFireRoomBuffs = selectedRoomName.Contains("Fire");
		lightStageEffects.Toggle(forceEmpowerDrop);
		airStageEffects.Toggle(applyAirRoomBuffs);
		foreach (KeyValuePair<string, GameObject> item in availableRoomDict)
		{
			if (item.Value != null)
			{
				if (item.Key == selectedRoomName)
				{
					selectedRoom = item.Value.GetComponent<Room>();
					item.Value.SetActive(value: true);
