					inputDetected = true;
				}
				yield return null;
			}
		}
		SoundManager.PlayBGM(string.Empty);
		matchInProgress = false;
		switch (selection)
		{
		case 0:
			ResetStage(fullReset: true);
			break;
		case 1:
			ResetStage(fullReset: true);
