	private void SetEventHandlers(bool givenStatus)
	{
		if (parentEntity == null)
		{
			return;
		}
		prevState = -1;
		StatManager.ModifyAllStatData(damageMod, parentSkillCategory, "damage", IgnoreStatusConditional, givenStatus);
		parentEntity.movement.moveSpeedStat.Modify(speedMod, givenStatus);
		OnInventoryChange(this, givenStatus);
		Inventory inventory = parentEntity.inventory;
		inventory.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Remove(inventory.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
		if (givenStatus)
		{
			Inventory inventory2 = parentEntity.inventory;
			inventory2.inventoryChangeEventHandler = (Inventory.ItemEventHandler)Delegate.Combine(inventory2.inventoryChangeEventHandler, new Inventory.ItemEventHandler(OnInventoryChange));
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null) && !(player == parentEntity) && player.inventory.ContainsItem(ID) && player.inventory.inventoryChangeEventHandler != null)
			{
				player.inventory.inventoryChangeEventHandler(this, givenStatus);
			}
		}
	}
	private void OnInventoryChange(Item givenItem, bool givenStatus)
	{
		if (givenItem == null || givenItem.ID != ID)
		{
			return;
		}
		if (givenStatus)
		{
			if (Inventory.BothPlayersHaveItem(ID))
			{
				activeState = 3;
				UpdateItemBar(ItemStatusBar.ItemState.Active);
			}
			else if (GameController.coopOn)
			{
				activeState = 2;
				UpdateItemBar(ItemStatusBar.ItemState.Ready);
			}
			else
			{
				activeState = 1;
				UpdateItemBar(ItemStatusBar.ItemState.Disabled);
			}
		}
		else
		{
			if (givenItem == this)
			{
				RemoveFromItemBar();
				return;
			}
			if (GameController.coopOn)
			{
				activeState = 2;
				UpdateItemBar(ItemStatusBar.ItemState.Ready);
			}
			else
			{
				activeState = 1;
				UpdateItemBar(ItemStatusBar.ItemState.Disabled);
			}
		}
		if (activeState != prevState)
		{
			prevState = activeState;
			ApplyMods(activeState);
		}
	}
	private void ApplyMods(int givenState)
