		{
			menuOpt.color = Globals.uiNotSelectedColor;
			menuOpt.fontSize = TextManager.GetAdjustedFontSize(disabledFontSize);
		}
	}
	public bool AllowMultiplayer()
	{
		return ReInput.controllers.controllerCount > 1;
	}
	public void ConfirmMenuOption()
	{
		if (currentState != TitleScreenState.Menu)
		{
			return;
		}
		switch (currentMenuIndex)
		{
		case 0:
			SoundManager.PlayConfirmAudio();
			StartGame();
			break;
		case 1:
			if (!AllowMultiplayer())
			{
				SoundManager.PlayAudio("MenuError");
				GlobalDialog.Display("titleScreen-connect2ndController");
			}
			else
			{
				SoundManager.PlayConfirmAudio();
				StartGame();
				GameController.coopOn = true;
			}
			break;
		case 2:
			if (!AllowMultiplayer())
			{
				SoundManager.PlayAudio("MenuError");
				GlobalDialog.Display("titleScreen-connect2ndController");
			}
			else
			{
				SoundManager.PlayConfirmAudio();
				StartGame(loadPvP: true);
				GameController.coopOn = true;
			}
			break;
		case 3:
			currentState = TitleScreenState.Options;
			GameController.optionsMenu.gameObject.SetActive(value: true);
			GameController.optionsMenu.releaseControlToParent = false;
			Hide();
			SoundManager.PlayConfirmAudio();
			break;
		case 4:
			Credits.transitionToTitle = true;
			GameController.LoadLevel("Credits");
			SoundManager.PlayConfirmAudio();
			break;
		case 5:
			SoundManager.PlayConfirmAudio();
			GameController.Quit();
			break;
		}
	}
	public void StartGame(bool loadPvP = false)
	{
		masterMixer.FindSnapshot("Default").TransitionTo(0.3f);
		GameController.cameraController.disablePlayerTracking = false;
		GameController.cameraController.spawnPos = new Vector3(0f, 0f, -10f);
		GameController.cameraController.lockToSpawnPos = false;
		GameController.ClearLevelStats(fullReset: true);
		GameUI.SetMoneyStatus(!loadPvP);
		if (loadPvP)
		{
			GameController.LoadLevel("PvP");
		}
		else if (!GameDataManager.gameData.tutorialCleared)
		{
			GameController.LoadLevel("Tutorial");
		}
		else
		{
			GameController.LoadLevel("PlayerRoom");
		}
	}
}

using Chaos.AnimatorExtensions;
using UnityEngine;
using UnityEngine.UI;
public class LoadingScreen : MonoBehaviour
{
	public delegate void LoadCompleteEvent();
	private static LoadingScreen instance;
	private GameObject bgOverlay;
	private Text progressText;
	private Text promptText;
	private Canvas canvas;
	private Animator anim;
	private Text loopCounterText;
	public LoadCompleteEvent loadCompleteEventHandlers;
	public GameProgressBoard gameProgressBoard;
	private bool fadeOutQueued;
	private bool promptFadeIn;
	private bool useFlickering;
	private float fadeTime = 0.5f;
	private int fadeStopwatchID = -1;
	private bool mouseWasVisible;
	[HideInInspector]
	public bool queueDisableOnly;
	private bool waitingForTPAnim;
	private bool tpFrameSkipped;
	private AnimEffect tpEffect;
	private string prevLevelName;
	private int prevStageCount;
	private int prevTierCount;
	private string levelName;
	public static bool loading;
	public static LoadingScreen Instance => instance;
	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		bgOverlay = transform.Find("BlackOverlay").gameObject;
		progressText = transform.Find("BlackOverlay/Progress").GetComponent<Text>();
		promptText = transform.Find("BlackOverlay/Prompt").GetComponent<Text>();
		canvas = GetComponent<Canvas>();
		anim = GetComponent<Animator>();
		gameProgressBoard = transform.Find("GameProgress").GetComponent<GameProgressBoard>();
		loopCounterText = transform.Find("GameProgress/StartCircle/LoopCounter/Text").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, progressText);
		TextManager.AddUIRef(string.Empty, promptText);
		TextManager.AddUIRef(string.Empty, loopCounterText);
		Object.DontDestroyOnLoad(gameObject);
	}
	private void Start()
	{
		Disable();
	}
	private void Update()
	{
		if (loading && GameUI.pauseMenu.paused)
		{
			GameUI.TogglePause();
		}
		if (fadeOutQueued && gameProgressBoard.pieceFinishedMoving)
		{
			fadeOutQueued = false;
			FadeOut();
			return;
		}
		if (useFlickering && ChaosStopwatch.Check(fadeStopwatchID))
		{
			fadeStopwatchID = ChaosStopwatch.Begin(fadeTime);
			promptText.CrossFadeAlpha((!promptFadeIn) ? 0.6f : 1f, 0.25f, ignoreTimeScale: true);
			promptFadeIn = !promptFadeIn;
		}
		if (!waitingForTPAnim)
		{
			return;
		}
		if (!tpFrameSkipped)
		{
			tpFrameSkipped = true;
		}
		else if ((tpEffect == null || tpEffect.anim.AnimPlayed(0.25f) || !tpEffect.playing) && GameController.activePlayers.Length > 0)
		{
			AnnounceStage();
			waitingForTPAnim = false;
			StopLoading();
			tpFrameSkipped = false;
			tpEffect = null;
			GameController.PauseAllPlayers(state: false);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				player.Show();
			}
		}
	}
	public void SetProgressText(string txt)
	{
		progressText.text = txt;
	}
	public void SetPromptText(string txt)
	{
		promptText.text = txt;
	}
	public void Enable(bool gameProgressMode = false)
	{
		canvas.enabled = true;
		waitingForTPAnim = false;
		tpFrameSkipped = false;
		bgOverlay.SetActive(value: true);
		anim.Play("Enabled", -1, 0f);
		if (gameProgressMode)
		{
			gameProgressBoard.Enable();
		}
		if (!GameController.mouseCursor.Hidden)
		{
			mouseWasVisible = true;
			GameController.mouseCursor.Hide();
		}
		else
		{
			mouseWasVisible = false;
		}
		prevLevelName = Application.loadedLevelName;
		prevStageCount = GameController.stageCount;
		prevTierCount = GameController.tierCount;
		loopCounterText.enabled = true;
		loopCounterText.text = ((GameController.loopCount <= 0) ? string.Empty : ("x" + (GameController.loopCount + 1)));
		loading = true;
	}
	public void StopLoading()
	{
		loading = false;
		if ((prevLevelName != levelName || prevStageCount != GameController.stageCount || prevTierCount != GameController.tierCount) && loadCompleteEventHandlers != null)
		{
			loadCompleteEventHandlers();
		}
	}
	public void FadeOut()
	{
		if (gameProgressBoard.visible && !gameProgressBoard.pieceFinishedMoving)
		{
			fadeOutQueued = true;
			return;
		}
		anim.Play("FadeOut", -1, 0f);
		gameProgressBoard.Disable();
		SetProgressText(string.Empty);
		loopCounterText.enabled = false;
		if (mouseWasVisible)
		{
			GameController.mouseCursor.Show();
			mouseWasVisible = false;
		}
	}
	public void Disable()
	{
		canvas.enabled = false;
		bgOverlay.SetActive(value: false);
		if (queueDisableOnly)
		{
			queueDisableOnly = false;
			StopLoading();
			return;
		}
		levelName = Application.loadedLevelName;
		if (levelName == "Credits" || levelName == "PlayerRoomTutorial")
		{
			StopLoading();
			return;
		}
		if (levelName == "PvPArena")
		{
			StopLoading();
			GameController.PauseAllPlayers(state: false);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				player.Show();
			}
			return;
		}
		int num = -1;
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			if (num == -1)
			{
				num = player2.playerID;
				tpEffect = PoolManager.GetPoolItem<AnimEffect>("TeleportEffect");
				tpEffect.Play(player2.transform.position, string.Empty);
			}
			else
			{
				player2.TeleportToPartner(num, showSpawnPortal: false, excludeOrigin: true);
			}
			waitingForTPAnim = true;
		}
		if (Application.loadedLevelName == "Tutorial" && GameController.activePlayers.Length == 0)
		{
			StopLoading();
			waitingForTPAnim = true;
		}
		if (!waitingForTPAnim)
		{
			StopLoading();
			AnnounceStage();
		}
	}
	private void AnnounceStage()
	{
		if (NextLevelLoader.InTierScene(string.Empty))
		{
			GameController.stageTitleUI.Announce(GameController.StageTitle, 0f, 60, null, null, showUnderline: true, 1f, 0f, numberMode: false, null, null, null, 0.2f);
			return;
		}
		levelName = Application.loadedLevelName;
		if (levelName == "Hub" || levelName == "Tutorial")
		{
			GameController.stageTitleUI.Announce(TextManager.GetUIText("stageTitle-" + levelName));
		}
	}
}
using Chaos.AnimatorExtensions;
using UnityEngine;
public class Credits : MonoBehaviour
{
	public static bool transitionToTitle = true;
	private Animator anim;
	private bool transitionToNextScene;
	private bool transitionCalled;
	private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(2f);
	private void Awake()
	{
		anim = GetComponent<Animator>();
	}
	private void Start()
	{
		GameController.overlayEffects.anim.Play("BlackToTrans", -1, 0f);
		delayStopwatch.IsRunning = true;
	}
	private void Update()
	{
		if (!transitionToNextScene)
		{
			if (anim.AnimPlayed() || SkipRequested())
			{
				transitionToNextScene = true;
				GameController.overlayEffects.anim.Play("FadeToBlack", -1, 0f);
			}
		}
		else if (!transitionCalled && GameController.overlayEffects.anim.AnimPlayed())
		{
			GameController.overlayEffects.anim.Play("Hidden", -1, 0f);
			anim.Play("Hide", -1, 0f);
			if (transitionToTitle)
			{
				GameController.LoadLevel("TitleScreen");
			}
			else
			{
				GameUI.deathSummary.Activate(0f);
			}
			transitionCalled = true;
		}
	}
	private bool SkipRequested()
	{
		if (delayStopwatch.IsRunning)
		{
			return false;
		}
		return InputController.GetAnyDeviceButtonDown("Confirm") != null || InputController.GetAnyDeviceButtonDown("Cancel") != null;
	}
}

using System;
using System.Collections;
using Chaos.AnimatorExtensions;
using UnityEngine;
using UnityEngine.UI;
public class Epilogue : MonoBehaviour
{
	private PlayerRunData winnerData;
	public Transform outfitSpriteTrans;
	public Transform relicSpriteTrans;
	public Transform startBasicSpriteTrans;
	public Transform startDashSpriteTrans;
	public Transform startStandardSpriteTrans;
	public Transform startSigntaureSpriteTrans;
	private Transform tempTrans;
	private SpriteRenderer tempSR;
	private int tempCount;
	public Sprite paintingCoveredSprite;
	public SpriteRenderer[] npcPaintingSprites;
	public Sprite spellCoveredSprite;
	public SpriteRenderer[] spellRoomGlassSprites;
	public SpriteRenderer[] spellRoomIconSprites;
	private int spellRoomCount;
	public Transform[] relicRoomTrans;
	private int relicRoomCount = 12;
	public Transform otherStatuesTrans;
	public Transform otherDataTrans;
	public Transform otherOutfitSpriteTrans;
	public Transform otherRelicSpriteTrans;
	public Transform otherSignatureSpriteTrans;
	public Npc epilogueWorkerNpc;
	private bool wakeUpEventDone;
	private bool wakeUpEventStarted;
	private void Start()
	{
		winnerData = RunData.GetWinnerData();
		if (winnerData != null)
		{
			LoadStartOutfit();
			LoadStartRelic();
			LoadStartSpells();
			LoadNpcSprites();
			LoadSpellRoom();
			LoadRelicRoom();
			LoadCoopRoom(RunData.GetOtherData(winnerData.playerID));
			SetRunTimeClock();
		}
	}
	private void Update()
	{
		if (wakeUpEventDone)
		{
			enabled = false;
		}
		else if (!wakeUpEventStarted && !LoadingScreen.loading && GameController.activePlayers.Length > 0)
		{
			wakeUpEventStarted = true;
			StartCoroutine(WakeUpPlayers());
			LoadPlayerMuseumSpells();
		}
	}
	private IEnumerator WakeUpPlayers()
	{
		Player activePlayer = GameController.activePlayers[0];
		GameController.PauseAllPlayers();
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			player.anim.Play("DeadDown", -1, 1f);
		}
		yield return new WaitForSeconds(1f);
		epilogueWorkerNpc.myDialogID = "MuseumWorkerEpilogue-Landing0";
		epilogueWorkerNpc.ForcePlayerActivation(activePlayer);
		yield return null;
		while (DialogManager.dialogInProgress)
		{
			yield return null;
		}
		Animator playerAnim = null;
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			player2.anim.Play("GetUp", -1, 0f);
			playerAnim = player2.anim;
		}
		yield return null;
		while (playerAnim != null && !playerAnim.AnimPlayed())
		{
			yield return null;
		}
		yield return new WaitForSeconds(0.33f);
		epilogueWorkerNpc.myDialogID = "MuseumWorkerEpilogue-Landing1";
		epilogueWorkerNpc.enabled = true;
		epilogueWorkerNpc.ForcePlayerActivation(activePlayer);
		SoundManager.PlayEpilogueBGM();
		yield return null;
		while (DialogManager.dialogInProgress)
		{
			yield return null;
		}
		GameController.PauseAllPlayers(state: false);
		wakeUpEventDone = true;
	}
	private void SetRunTimeClock()
	{
		tempTrans = transform.Find("PlayerData/DigitalClock/Time");
		TimeSpan timeSpan = TimeSpan.FromSeconds(GameController.lastTotalTime);
		tempTrans.Find("Hours").GetComponent<Text>().text = $"{Mathf.Clamp(timeSpan.Hours, 0, 99):D2}";
		tempTrans.Find("Minutes").GetComponent<Text>().text = $"{Mathf.Clamp(timeSpan.Minutes, 0, 59):D2}";
		tempTrans.Find("Seconds").GetComponent<Text>().text = $"{Mathf.Clamp(timeSpan.Seconds, 0, 59):D2}";
	}
	private void LoadPlayerMuseumSpells()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null))
			{
				player.AssignSkillSlot(0, Player.WindSlashBasic.staticID);
				player.AssignSkillSlot(1, Player.DashState.staticID);
				player.AssignSkillSlot(2, Player.ShootFireArc.staticID);
				player.AssignSkillSlot(3, Player.ShootFireball.staticID, setSignature: true, signatureStatus: true);
				player.lowerHUD.cooldownUI.RefreshEntries();
			}
		}
	}
	private void LoadStartOutfit()
	{
		if (outfitSpriteTrans == null)
		{
			return;
		}
		tempSR = outfitSpriteTrans.GetComponent<SpriteRenderer>();
		if (tempSR != null && Outfit.OutfitDict.ContainsKey(winnerData.startOutfit))
		{
			tempSR.material = new Material(tempSR.material);
			tempSR.material.SetFloat("_PaletteIndex", Outfit.OutfitDict[winnerData.startOutfit].outfitColorIndex);
			if (winnerData.outFitEnhanced)
			{
				Globals.ChaosInst<Transform>(TailorNpc.SparklePrefab, tempSR.transform, tempSR.transform.position + Vector3.up * 1.25f);
			}
		}
	}
	private void LoadStartRelic()
	{
		LoadSprite(relicSpriteTrans, winnerData.startItem);
	}
	private void LoadStartSpells()
	{
		LoadSprite(startBasicSpriteTrans, winnerData.startSpellBasic, isItem: false);
		LoadSprite(startDashSpriteTrans, winnerData.startSpellDash, isItem: false);
		LoadSprite(startStandardSpriteTrans, winnerData.startSpellStandard, isItem: false);
		LoadSprite(startSigntaureSpriteTrans, winnerData.startSpellSignature, isItem: false);
	}
	private void LoadNpcSprites()
	{
		tempCount = 0;
		if (RunData.reqSkillStoreFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("SkillMerchantPainting");
			tempCount++;
		}
		if (RunData.reqItemStoreFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("ItemMerchantPainting");
			tempCount++;
		}
		if (RunData.miscCursedStoreFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("CursedMerchantPainting");
			tempCount++;
		}
		if (RunData.miscNurseRoomFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("DoctorPainting");
			tempCount++;
		}
		if (RunData.miscSlotsRoomFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("ShufflerPainting");
			tempCount++;
		}
		if (RunData.miscCollectorRoomFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("CollectorPainting");
			tempCount++;
		}
		if (RunData.miscTailorRoomFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("OutfitNPCPainting");
			tempCount++;
		}
		if (RunData.miscPinataRoomFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("PinataPainting");
			tempCount++;
		}
		if (RunData.miscBankerRoomFound)
		{
			npcPaintingSprites[tempCount].sprite = IconManager.GetPainting("BankerPainting");
			tempCount++;
		}
		for (int i = tempCount; i < npcPaintingSprites.Length; i++)
		{
			npcPaintingSprites[i].sprite = paintingCoveredSprite;
		}
	}
	private void LoadSpellRoom()
	{
		spellRoomCount = spellRoomGlassSprites.Length;
		bool flag = winnerData.endSpellStock != string.Empty;
		int num = spellRoomCount - 1;
		if (flag)
		{
			spellRoomIconSprites[num].sprite = IconManager.GetSkillIcon(winnerData.endSpellStock);
		}
		for (int i = 0; i < spellRoomCount; i++)
		{
			if (i < winnerData.endSpellList.Count)
			{
				spellRoomIconSprites[i].sprite = IconManager.GetSkillIcon(winnerData.endSpellList[i]);
			}
			else if (!flag || i != num)
			{
				spellRoomGlassSprites[i].sprite = spellCoveredSprite;
				spellRoomIconSprites[i].transform.parent.gameObject.SetActive(value: false);
			}
		}
	}
	private void LoadRelicRoom()
	{
		tempTrans = transform.Find("RelicRoom/Podium");
		if (!(tempTrans == null))
		{
			relicRoomTrans = new Transform[relicRoomCount];
			for (int i = 0; i < relicRoomCount; i++)
			{
				relicRoomTrans[i] = tempTrans.Find("Relic" + i + "/ItemIcon");
			}
			tempCount = Mathf.Min(relicRoomCount, winnerData.endRelicList.Count);
			for (int j = 0; j < tempCount; j++)
			{
				LoadSprite(relicRoomTrans[j], winnerData.endRelicList[j]);
			}
			for (int k = tempCount; k < relicRoomCount; k++)
			{
				relicRoomTrans[k].parent.gameObject.SetActive(value: false);
			}
		}
	}
	private void LoadCoopRoom(PlayerRunData givenData)
	{
		if (!GameController.coopOn || givenData == null)
		{
			otherDataTrans.gameObject.SetActive(value: false);
			return;
		}
		otherStatuesTrans.gameObject.SetActive(value: false);
		tempSR = otherOutfitSpriteTrans.GetComponent<SpriteRenderer>();
		if (tempSR != null && Outfit.OutfitDict.ContainsKey(givenData.startOutfit))
		{
			tempSR.material = new Material(tempSR.material);
			tempSR.material.SetFloat("_PaletteIndex", Outfit.OutfitDict[givenData.startOutfit].outfitColorIndex);
			if (givenData.outFitEnhanced)
			{
				Globals.ChaosInst<Transform>(TailorNpc.SparklePrefab, tempSR.transform, tempSR.transform.position + Vector3.up * 1.25f);
			}
		}
		LoadSprite(otherSignatureSpriteTrans, givenData.startSpellSignature, isItem: false);
		LoadSprite(otherRelicSpriteTrans, givenData.startItem);
	}
	private void LoadSprite(Transform givenTrans, string givenID, bool isItem = true)
	{
		if (!(givenTrans == null))
		{
			tempSR = givenTrans.GetComponent<SpriteRenderer>();
			if (!(tempSR == null))
			{
				tempSR.sprite = ((!isItem) ? IconManager.GetSkillIcon(givenID) : IconManager.GetItemIcon(givenID));
			}
		}
	}
}

