public static string GetLockedChaosArcana(bool prefStandard = false)
{
	if (prefStandard)
	{
		chaosStandardList.Shuffle();
		foreach (string chaosStandard in chaosStandardList)
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player.skillsDict.ContainsKey(chaosStandard) && !player.skillsDict[chaosStandard].isUnlocked)
				{
					return chaosStandard;
				}
			}
		}
	}
	chaosSkillList.Shuffle();
	foreach (string chaosSkill in chaosSkillList)
	{
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			if (player2.skillsDict.ContainsKey(chaosSkill) && (!player2.skillsDict[chaosSkill].isUnlocked || (player2.skillsDict[chaosSkill].hasSignatureVariant && !player2.skillsDict[chaosSkill].signatureUnlocked)))
			{
				return chaosSkill;
			}
		}
	}
	return string.Empty;
}

public static string GetSkillID(bool locked = false, bool signature = false)
{
	string text = string.Empty;
	if (signature)
	{
		if (lockedSigList.Count > 0)
		{
			text = lockedSigList[Random.Range(0, lockedSigList.Count)];
		}
	}
	else if (locked)
	{
		if (lockedSkillList.Count > 0)
		{
			text = lockedSkillList[Random.Range(0, lockedSkillList.Count)];
		}
	}
	else if (availableSkillList.Count > 0)
	{
		text = availableSkillList[Random.Range(0, availableSkillList.Count)];
	}
	if (text != string.Empty)
	{
		lockedSigList.Remove(text);
		lockedSkillList.Remove(text);
		availableSkillList.Remove(text);
	}
	return text;
}

public static void DropSkill(Vector3 spawnLocation, int amount, string skillID = "", float lockedSkillDropRate = 0f, float signatureSkillDropRate = 0f, HashSet<ElementType> elementSet = null, bool useLifeTime = false, bool isEmpowered = false)
{
	bool flag = signatureSkillDropRate > 0f && signatureSkillDropRate > Random.value;
	for (int i = 0; i < amount; i++)
	{
		string text = string.Empty;
		if (skillID != string.Empty)
		{
			text = skillID;
		}
		else
		{
			if (Random.value > lockedSkillDropRate)
			{
				text = GetSkillID(locked: true, flag);
			}
			if (text == string.Empty)
			{
				bool signature = flag;
				text = GetSkillID(locked: false, signature);
			}
			if (text == string.Empty)
			{
				text = GetSkillID();
			}
		}
		if (text == string.Empty || text == noDropID)
		{
			continue;
		}
		bool flag2 = false;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player.skillsDict.ContainsKey(text))
			{
				Player.SkillState skillState = player.skillsDict[text];
				if (flag)
				{
					text = ((!skillState.hasSignatureVariant) ? (text + "Empowered") : (text + "Signature"));
				}
				else if (isEmpowered)
				{
					text += "Empowered";
				}
				flag2 = true;
			}
			if (flag2)
			{
				break;
			}
		}
		if (flag2)
		{
			ItemSpawner itemSpawner = GameController.itemSpawner;
			ItemSpawner.PoolType poolType = ItemSpawner.PoolType.SkillDrop;
			Vector2 spawnLocation2 = spawnLocation;
			string otherValue = text;
			itemSpawner.SpawnItem(poolType, spawnLocation2, randomizeSpawnLocation: true, 1.5f, otherValue, useMinDist: true, useLifeTime);
			SoundManager.PlayAudio("DropSpell");
		}
	}
}

public static void DropItem(Vector3 spawnLocation, int amount, string itemID = "", bool randomLoc = true, float curseChance = 0.1f)
{
	for (int i = 0; i < amount; i++)
	{
		itemID = ((!(itemID == string.Empty) && i <= 0) ? itemID : GetAvailableItemID(curseChance));
		if (!(itemID == string.Empty) && !(itemID == noDropID))
		{
			GameController.itemSpawner.SpawnItem(ItemSpawner.PoolType.ItemDrop, spawnLocation, randomLoc, 1.5f, itemID, useMinDist: true);
			SoundManager.PlayAudio("DropItem");
		}
	}
}

