using System.Collections.Generic;
using UnityEngine;
public class CharacterSelectUI : MonoBehaviour
{
	private static CharacterSelectUI instance;
	public static PlayerCharacterSelectUI P1CharacterSelectUI;
	public static PlayerCharacterSelectUI P2CharacterSelectUI;
	private string levelName;
	private Canvas canvas;
	private bool sceneIsAvailable;
	private List<string> availableSceneList = new List<string>
	{
		"PlayerRoom", "Tutorial", "Design", "Test", "Boss", "Hub", "Dev", "SSS", "PvP", "Ending",
		"Epilogue"
	};
	public static CharacterSelectUI Instance => instance;
	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		P1CharacterSelectUI = transform.Find("P1CharacterSelect").GetComponent<PlayerCharacterSelectUI>();
		P2CharacterSelectUI = transform.Find("P2CharacterSelect").GetComponent<PlayerCharacterSelectUI>();
		gameObject.SetActive(value: false);
		Object.DontDestroyOnLoad(gameObject);
		canvas = GetComponent<Canvas>();
	}
	public void Update()
	{
		levelName = Application.loadedLevelName;
		sceneIsAvailable = false;
		foreach (string availableScene in availableSceneList)
		{
			if (levelName.Contains(availableScene))
			{
				sceneIsAvailable = true;
				break;
			}
		}
		if (sceneIsAvailable && !LoadingScreen.loading && (!P1CharacterSelectUI.activated || !P2CharacterSelectUI.activated))
		{
			if (!P1CharacterSelectUI.activated && !GameController.p1Joined)
			{
				P1CharacterSelectUI.Activate();
			}
			if (GameController.coopOn && !P2CharacterSelectUI.activated && !GameController.p2Joined)
			{
				P2CharacterSelectUI.Activate();
			}
		}
	}
	public void Activate()
	{
		gameObject.SetActive(value: true);
		canvas.enabled = true;
	}
	public void Disable()
	{
		P1CharacterSelectUI.Disable();
		P2CharacterSelectUI.Disable();
		gameObject.SetActive(value: false);
		canvas.enabled = false;
	}
}

