{
	return dividend - divisor * Mathf.Floor(dividend / divisor);
}

public static Vector2 GetCirclePositionVector(int totalCount, int position)
{
	if (totalCount == 0)
	{
		return Vector2.zero;
	}
	posVecAngle = (float)Math.PI * 2f / (float)totalCount * (float)position;
	return new Vector2(Mathf.Sin(posVecAngle), Mathf.Cos(posVecAngle));
}

public static Vector2 GetRotatedCircleVector(int totalCount, int position, Vector2 givenVector)
{
	if (totalCount == 0)
	{
		return givenVector;
	}
	posVecAngle = 360f / (float)totalCount * (float)position;
	return Quaternion.Euler(0f, 0f, posVecAngle) * givenVector;
}

