		}
		if (angle <= -112.5f && angle >= -157.5f)
		{
			return MapOrdinalDirections.SouthEast;
		}
	}
	else
	{
		if ((angle >= 337.5f && angle <= 0f) || (angle >= 0f && angle <= 22.5f))
		{
			return MapOrdinalDirections.North;
		}
		if (angle >= 22.5f && angle <= 67.5f)
		{
			return MapOrdinalDirections.NorthEast;
		}
		if ((double)angle >= 67.5 && angle <= 112.5f)
		{
			return MapOrdinalDirections.East;
		}
		if ((double)angle >= 112.5 && angle <= 157.5f)
		{
			return MapOrdinalDirections.SouthEast;
		}
		if ((double)angle >= 157.5 && angle <= 202.5f)
		{
			return MapOrdinalDirections.South;
		}
		if ((double)angle >= 202.5 && angle <= 247.5f)
		{
			return MapOrdinalDirections.SouthWest;
		}
		if ((double)angle >= 247.5 && angle <= 292.5f)
		{
			return MapOrdinalDirections.West;
		}
		if ((double)angle >= 292.5 && (double)angle <= 337.5)
		{
			return MapOrdinalDirections.NorthWest;
		}
	}
	return MapOrdinalDirections.East;
}

