using System.Collections.Generic;
using UnityEngine;
namespace Chaos.ListExtensions;
public static class ListExtension
{
	public static T GetRandomValue<T>(this List<T> list, int startIndex = 0)
	{
		return list[UnityEngine.Random.Range(startIndex, list.Count)];
	}
	public static void Shuffle<T>(this IList<T> list)
	{
		System.Random random = new System.Random();
		int num = list.Count;
		while (num > 1)
		{
			num--;
			int index = random.Next(num + 1);
			T value = list[index];
			list[index] = list[num];
			list[num] = value;
		}
	}
	public static void RemoveNullValues<T>(this IList<T> list)
	{
		if (list == null)
		{
			return;
		}
		for (int num = list.Count - 1; num >= 0; num--)
		{
			if (list[num] == null || list[num].ToString() == "null")
			{
				list.RemoveAt(num);
			}
		}
	}
}

