		}
	}
	private void StopAudio()
	{
		if (odLoopAudio != null)
		{
			odLoopAudio.Stop();
			odLoopAudio = null;
			SoundManager.PlayAudioWithDistance("FireBlastODEnd", spawnTransform.position);
		}
	}
